import React,{useState,useEffect,useRef,useCallback} from 'react';
import {createRoot} from 'react-dom/client';
import {motion,AnimatePresence,MotionConfig,useReducedMotion,useIsPresent} from 'motion/react';
import {Sun,Map,Leaf,SlidersHorizontal,Plus,Check,ChevronRight,ChevronLeft,ChevronDown,MoreHorizontal,X,Bell,BellOff,Flame,Star,CalendarDays,Clock,Repeat2,Flag,Search,ArrowRight,ArrowUpRight,Trash2,RotateCcw,Pause,Play,Target,Sparkles,BookOpen,Heart,Briefcase,Palette,Download,Cloud,WifiOff,CheckCheck,ShieldCheck,Inbox,Settings2,Send,Moon,Archive,LoaderCircle,Link,Volume2} from 'lucide-react';
import './style.css';

const BASE=location.pathname.match(/^\/app\/[^/]+\//)?.[0]||'/';
const uid=()=>crypto.randomUUID();
const dateAdd=(d,n)=>{const date=new Date(d+'T12:00:00Z');date.setUTCDate(date.getUTCDate()+n);return date.toISOString().slice(0,10);};
const dayLabel=d=>new Date(d+'T12:00:00Z').toLocaleDateString('zh-CN',{month:'long',day:'numeric',timeZone:'UTC'});
const weekday=d=>new Date(d+'T12:00:00Z').toLocaleDateString('zh-CN',{weekday:'long',timeZone:'UTC'});
const icons={生活:Leaf,工作:Briefcase,学习:BookOpen,健康:Heart,创作:Palette};
const statusLabel={todo:'未开始',doing:'进行中',done:'已完成',paused:'已暂停'};
function dueText(d,now=Date.now()){
  if(!d)return '';
  const n=Math.ceil((Date.parse(d)-now)/60000),abs=Math.abs(n);
  const value=abs<60?Math.max(1,abs)+' 分钟':abs<1440?Math.floor(abs/60)+' 小时':Math.ceil(abs/1440)+' 天';
  return n<0?'已逾期 '+value:'剩余 '+value;
}
function localParts(iso,zone='Asia/Shanghai'){
  if(!iso)return {day:'',time:''};
  const p=new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(iso)),o=Object.fromEntries(p.map(x=>[x.type,x.value]));
  return {day:o.year+'-'+o.month+'-'+o.day,time:o.hour+':'+o.minute};
}
function zonedISO(day,time,zone='Asia/Shanghai'){
  const target=Date.parse(day+'T'+time+':00Z');let ms=target;
  for(let i=0;i<3;i++){const p=localParts(new Date(ms).toISOString(),zone);ms+=target-Date.parse(p.day+'T'+p.time+':00Z');}
  return new Date(ms).toISOString();
}
async function request(path,method='GET',data){
  const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);
  try{
    const r=await fetch(BASE+'api/'+path,{method,headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined,signal:controller.signal,cache:'no-store'});
    const json=await r.json();if(!r.ok)throw Object.assign(Error(json.error||'保存失败'),{status:r.status});return json;
  }catch(e){if(e.name==='AbortError')throw Error('连接有点慢。内容还在，请稍后重试。');if(e instanceof TypeError)throw Error('暂时连不上服务器。请检查网络后重试。');throw e;}finally{clearTimeout(timer);}
}
function Sprout({mood='happy',className=''}){return <svg className={'sprout '+className} viewBox="0 0 180 190" fill="none" role="img" aria-label="芽芽陪你一起成长">
  <ellipse cx="89" cy="172" rx="49" ry="9" fill="#173d26" opacity=".12"/>
  <g className="sprout-body"><path d="M85 50C53 45 28 68 30 106L33 133C35 158 57 170 88 170C126 170 149 152 149 122V105C149 69 126 46 99 50Z" fill="#9ADF45"/><path d="M40 108C41 145 58 158 95 157C119 157 137 146 145 129C141 156 118 170 88 170C56 170 35 157 33 133Z" fill="#7CC82E"/>
  <path d="M42 111C19 105 17 120 29 132L43 138" fill="#9ADF45"/><path d="M141 105C157 83 172 92 162 108L144 128" fill="#9ADF45"/>
  <ellipse cx="63" cy="165" rx="17" ry="8" fill="#6EAD2C"/><ellipse cx="115" cy="165" rx="17" ry="8" fill="#6EAD2C"/>
  <path d="M89 55C78 26 89 13 108 13C114 32 108 43 90 53Z" fill="#58A82F"/><path d="M90 51C72 31 55 30 51 42C56 55 72 62 90 56Z" fill="#78C83B"/>
  <ellipse cx="65" cy="105" rx="8" ry="11" fill="#254332"/><ellipse cx="114" cy="105" rx="8" ry="11" fill="#254332"/><circle cx="67" cy="101" r="2.5" fill="white"/><circle cx="116" cy="101" r="2.5" fill="white"/>
  <ellipse cx="51" cy="124" rx="10" ry="5" fill="#F3A6A3" opacity=".8"/><ellipse cx="131" cy="124" rx="10" ry="5" fill="#F3A6A3" opacity=".8"/>
  {mood==='sleep'?<path d="M83 128H96" stroke="#254332" strokeWidth="5" strokeLinecap="round"/>:<path d="M79 125Q90 139 102 124" stroke="#254332" strokeWidth="5" strokeLinecap="round"/>}
  </g><path d="M152 28L155 37L164 40L155 43L152 52L149 43L140 40L149 37Z" fill="#FFD770"/><circle cx="25" cy="61" r="4" fill="#AEDFEA"/></svg>;}
function Progress({value,color='green',label}){return <div className={'progress-track '+color} role="progressbar" aria-label={label||'完成进度'} aria-valuenow={value} aria-valuemin={0} aria-valuemax={100}><motion.div initial={false} animate={{width:value+'%'}} transition={{type:'spring',stiffness:130,damping:23}}/><span/></div>;}
function Ring({value,size=56}){const r=22,c=2*Math.PI*r;return <svg width={size} height={size} viewBox="0 0 56 56" className="ring" aria-label={'已完成 '+value+'%'}><circle cx="28" cy="28" r={r} fill="none" stroke="currentColor" opacity=".13" strokeWidth="6"/><motion.circle cx="28" cy="28" r={r} fill="none" stroke="currentColor" strokeWidth="6" strokeLinecap="round" strokeDasharray={c} initial={false} animate={{strokeDashoffset:c*(1-value/100)}} transform="rotate(-90 28 28)"/><text x="28" y="32" textAnchor="middle" fill="currentColor" fontSize="12" fontWeight="850">{value}%</text></svg>;}
function Modal({title,children,onClose,wide=false}){
  const box=useRef(null),present=useIsPresent();
  useEffect(()=>{const prev=document.activeElement,old=document.body.style.overflow;document.body.style.overflow='hidden';const input=(box.current?.querySelector('input:not([type=range]),textarea')||box.current?.querySelector('button'));input?.focus({preventScroll:true});
    function key(e){if(e.key==='Escape'){e.preventDefault();onClose();}if(e.key==='Tab'){const all=[...box.current.querySelectorAll('button:not(:disabled),input:not(:disabled),select,textarea,a[href]')].filter(e=>e.offsetParent);const first=all[0],last=all.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}}
    document.addEventListener('keydown',key);return()=>{document.body.style.overflow=old;document.removeEventListener('keydown',key);prev?.focus?.({preventScroll:true});};
  },[]);
  return <motion.div className="modal-shade" style={{pointerEvents:present?"auto":"none"}} initial={{opacity:0}} animate={{opacity:1}} exit={{opacity:0}} onClick={e=>e.target===e.currentTarget&&onClose()}><motion.section ref={box} role="dialog" aria-modal="true" aria-label={title} className={'sheet '+(wide?'wide':'')} initial={{y:65,opacity:0,scale:.98}} animate={{y:0,opacity:1,scale:1}} exit={{y:80,opacity:0}} transition={{type:'spring',stiffness:340,damping:32}}><div className="sheet-handle"/><header className="sheet-header"><h2>{title}</h2><button className="icon-button" onClick={onClose} aria-label="关闭"><X size={22}/></button></header>{children}</motion.section></motion.div>;
}
function Empty({title='给今天，留一点期待',text='不用安排得满满当当。一件想做的小事，就是很好的开始。',action,label='添加第一件小事',samples}){
  return <div className="empty"><Sprout/><h3>{title}</h3><p>{text}</p>{action&&<button className="button primary" onClick={action}><Plus size={18}/>{label}</button>}{samples&&<button className="text-button" onClick={samples}>先逛逛示例计划 <ArrowRight size={16}/></button>}</div>;
}
function App(){
  const [state,setState]=useState(null),[bootError,setBootError]=useState(''),[page,setPage]=useState('today'),[day,setDay]=useState(''),[filter,setFilter]=useState('all'),[query,setQuery]=useState(''),[modal,setModal]=useState(null),[busy,setBusy]=useState(false),[toast,setToast]=useState(null),[party,setParty]=useState(0),[online,setOnline]=useState(navigator.onLine),[now,setNow]=useState(Date.now()),[permission,setPermission]=useState('Notification' in window?Notification.permission:'unsupported');
  const busyRef=useRef(false),modalRef=useRef(null),todayRef=useRef(null),toastTimer=useRef(),reduced=useReducedMotion();
  useEffect(()=>{modalRef.current=modal;},[modal]);
  const accept=useCallback(s=>{setState(s);setBootError('');setNow(s.serverTime||Date.now());const oldToday=todayRef.current;setDay(d=>!d||d===oldToday?s.today:d);todayRef.current=s.today;},[]);
  const refresh=useCallback(async()=>{try{accept(await request('state'));}catch(e){setBootError(e.message);}},[accept]);
  useEffect(()=>{refresh();const poll=setInterval(()=>{setNow(Date.now());if(!document.hidden&&!busyRef.current&&!modalRef.current)refresh();},30000);const focus=()=>{setOnline(navigator.onLine);if(!busyRef.current)refresh();};window.addEventListener('online',focus);window.addEventListener('offline',focus);const visible=()=>{if(!document.hidden)focus();};document.addEventListener('visibilitychange',visible);return()=>{clearInterval(poll);window.removeEventListener('online',focus);window.removeEventListener('offline',focus);document.removeEventListener('visibilitychange',visible);};},[]);
  useEffect(()=>{if(state){const t=state.settings.theme;document.documentElement.dataset.theme=t==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):t;}},[state?.settings.theme]);
  useEffect(()=>{if('serviceWorker' in navigator&&window.isSecureContext)navigator.serviceWorker.register(BASE+'sw.js',{scope:BASE}).catch(()=>{});},[]);
  useEffect(()=>{const onSW=e=>{if(e.data?.taskId)setModal({type:'detail',id:e.data.taskId});};navigator.serviceWorker?.addEventListener('message',onSW);return()=>navigator.serviceWorker?.removeEventListener('message',onSW);},[]);
  useEffect(()=>{if(state){const id=new URLSearchParams(location.search).get('task');if(id&&state.tasks.some(t=>t.id===id)){setModal({type:'detail',id});history.replaceState({},'',BASE);}}},[!!state]);
  function notify(message,action){clearTimeout(toastTimer.current);setToast({message,action});toastTimer.current=setTimeout(()=>setToast(null),action?7500:4500);}
  async function mutate(path,method,data,{close=false,success,optimistic}={}){
    if(busyRef.current)return null;busyRef.current=true;setBusy(true);const before=state;
    if(optimistic)setState(optimistic(state));
    try{const result=await request(path,method,data);if(result.state)accept(result.state);else if(result.tasks)accept(result);if(close)setModal(null);if(success)notify(success);return result;}
    catch(e){if(optimistic)setState(before);notify(e.message);if(e.status===409)await refresh();return null;}
    finally{busyRef.current=false;setBusy(false);}
  }
  function celebrate(){if(state.settings.celebrate&&!reduced){setParty(Date.now());setTimeout(()=>setParty(0),1800);}}
  async function patchTask(task,patch,opts={}){
    const r=await mutate('tasks/'+task.id,'PATCH',{patch,version:task.version},opts);
    if(r&&((r.task.status==='done'&&task.status!=='done')||r.task.steps.filter(s=>s.done).length>task.steps.filter(s=>s.done).length))celebrate();return r;
  }
  async function toggle(task){
    const done=task.status!=='done',previous={status:task.status,progress:task.progress,steps:task.steps};
    const patch=done?{status:'done'}:{status:'todo'};
    const r=await patchTask(task,patch,{optimistic:s=>({...s,tasks:s.tasks.map(t=>t.id===task.id?{...t,status:done?'done':'todo',progress:done?100:0}:t)})});
    if(r)notify(done?'又前进了一小步，做得不错！':'已重新放回计划',{label:'撤销',run:()=>patchTask(r.task,previous)});
  }
  async function remove(task){
    const result=await mutate('tasks/'+task.id,'DELETE',{version:task.version},{close:true});
    if(result)notify('已移到回收站',{label:'撤销',run:()=>mutate('tasks/'+task.id+'/restore','POST',{})});
  }
  async function enablePush(){
    const standalone=matchMedia('(display-mode: standalone)').matches||navigator.standalone;
    const iOS=/iPhone|iPad|iPod/.test(navigator.userAgent);
    if(iOS&&!standalone){setModal({type:'install'});return;}
    if(!('Notification' in window)||!('PushManager' in window)||!('serviceWorker' in navigator)){notify('请在 iPhone 上用 Safari 添加到主屏幕后开启通知');return;}
    try{
      const p=await Notification.requestPermission();setPermission(p);
      if(p!=='granted'){notify('通知尚未允许。可在 iPhone 设置 → 通知 → 小步中开启。');return;}
      const reg=await navigator.serviceWorker.ready;
      let subscription=await reg.pushManager.getSubscription();
      if(!subscription){const key=state.push.publicKey,padded=(key+'='.repeat((4-key.length%4)%4)).replace(/-/g,'+').replace(/_/g,'/');subscription=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:Uint8Array.from(atob(padded),x=>x.charCodeAt(0))});}
      await mutate('push/subscribe','POST',{subscription:subscription.toJSON()},{success:'通知连接成功，重要的事会来找你'});
    }catch(e){notify(e.message||'连接通知失败，请稍后再试');}
  }
  const openAdd=(kind='task')=>setModal({type:'form',kind});
  if(!state)return <div className="boot"><Sprout/><h1>小步</h1><p>{bootError||'给每一天，一点向前的力量。'}</p>{bootError?<button className="button primary" onClick={refresh}>重新连接</button>:<LoaderCircle className="spin"/>}</div>;
  const {tasks,stats,settings,today}=state;
  const selected=tasks.find(t=>t.id===modal?.id);
  const todayTasks=tasks.filter(t=>t.kind==='task'&&t.day===day),done=todayTasks.filter(t=>t.status==='done').length;
  const percent=todayTasks.length?Math.round(done/todayTasks.length*100):0;
  const overdue=tasks.filter(t=>t.kind==='task'&&t.day<today&&!['done','paused'].includes(t.status));
  const matches=t=>(!query||t.title.toLowerCase().includes(query.toLowerCase())||t.note.toLowerCase().includes(query.toLowerCase()))&&(filter==='all'||(filter==='active'?t.status!=='done':t.status===filter));
  const list=[...todayTasks].filter(matches).sort((a,b)=>(a.status==='done')-(b.status==='done')||(b.priority==='high')-(a.priority==='high')||(a.dueAt||'z').localeCompare(b.dueAt||'z'));
  const goals=tasks.filter(t=>t.kind==='goal'),goal=goals.find(t=>t.status!=='done'&&t.status!=='paused');
  const nav=[{id:'today',label:'今天',icon:Sun},{id:'plans',label:'长期计划',icon:Map},{id:'growth',label:'成长足迹',icon:Leaf},{id:'settings',label:'我的',icon:SlidersHorizontal}];
  const changePage=id=>{setPage(id);setQuery('');setFilter('all');window.scrollTo({top:0,behavior:'instant'});};
  const sample=tasks.some(t=>t.sample);
  return <MotionConfig reducedMotion="user"><div className="app-shell" inert={!!modal}>
    <aside className="sidebar"><button className="brand" onClick={()=>changePage('today')} aria-label="小步首页"><span className="brand-mark"><Leaf size={27} strokeWidth={3}/></span><span>小步<small>SMALL STEPS, BIG DAYS</small></span></button><nav>{nav.map(n=><button key={n.id} className={'side-nav '+(page===n.id?'active':'')} onClick={()=>changePage(n.id)}><n.icon size={22}/><span>{n.label}</span>{page===n.id&&<span className="nav-dot"/>}</button>)}</nav><div className="sidebar-bottom"><Sprout/><p>每一小步<br/><strong>都算数。</strong></p><button onClick={()=>setModal({type:'install'})} className="subtle-link"><ArrowUpRight size={16}/>添加到手机桌面</button></div><div className="private-label"><ShieldCheck size={14}/> 只属于你的计划空间</div></aside>
    <div className="workspace"><header className="topbar"><div className="mobile-brand"><span className="brand-mark"><Leaf size={22} strokeWidth={3}/></span>小步</div><div className="breadcrumb">我的空间 <span>/</span> {nav.find(n=>n.id===page).label}</div><div className="topbar-actions"><span className="streak"><Flame size={19} fill="currentColor"/><b>{stats.streak}</b><span>天连续行动</span></span><button className="icon-button notification-button" onClick={()=>setModal({type:'notifications'})} aria-label="通知记录"><Bell size={21}/>{state.notifications.some(n=>n.status==='shown')&&<i/>}</button><button className="avatar" onClick={()=>changePage('settings')} aria-label="我的设置">{settings.name==='你'?'小':settings.name.slice(0,1)}</button></div></header>
    {(!online||bootError)&&<div className="connection-banner" role="status"><WifiOff size={17}/>{!online?'当前离线，恢复网络后即可保存。':bootError}<button onClick={refresh}>重试</button></div>}
    <div className="content-grid"><main className={'main-content page-'+page}>
    <AnimatePresence mode="wait" initial={false}><motion.div key={page} initial={{opacity:0,y:10}} animate={{opacity:1,y:0}} exit={{opacity:0,y:-5}} transition={{duration:.2}}>
    {page==='today'&&<>
      <div className="page-heading"><div><p className="eyebrow">{dayLabel(day)} · {weekday(day)}</p><h1>{day===today?'今天，也向前一点':dayLabel(day)+'的计划'}<span className="heading-spark">✦</span></h1><p className="muted">把想做的事，变成做过的事。</p></div><button className="button primary desktop-add" onClick={()=>openAdd()}><Plus size={19}/>添加任务</button></div>
      <section className="today-hero"><div className="hero-copy"><span className="hero-label"><Sun size={15}/> 今日小目标</span><h2>{percent===100&&todayTasks.length?'今天的你，闪闪发光。':done?'已经开始，就很了不起。':'不用很厉害，先开始。'}</h2><p>{todayTasks.length?'完成 '+done+' / '+todayTasks.length+' 件小事，积攒一点成就感。':'从一件小事开始，让今天有一点不同。'}</p><div className="hero-progress"><Progress value={percent}/><b>{percent}%</b></div></div><div className="hero-mascot"><div className="mascot-orbit"/><Sprout/><span className="hero-star star-one">✦</span><span className="hero-star star-two">✦</span></div></section>
      <div className="week-bar"><button className="icon-button" onClick={()=>setDay(dateAdd(day,-7))} aria-label="上一周"><ChevronLeft size={18}/></button>{Array.from({length:7},(_,i)=>{const start=dateAdd(day,-((new Date(day+'T12:00:00Z').getUTCDay()+6)%7)),d=dateAdd(start,i);return <button key={d} className={'day-button '+(d===day?'selected':'')+(d===today?' is-today':'')} onClick={()=>setDay(d)} aria-label={dayLabel(d)+(d===today?' 今天':'')} aria-pressed={d===day}><span>{['一','二','三','四','五','六','日'][i]}</span><b>{Number(d.slice(-2))}</b><i className={tasks.some(t=>t.day===d&&t.kind==='task')?'has-task':''}/></button>;})}<button className="icon-button" onClick={()=>setDay(dateAdd(day,7))} aria-label="下一周"><ChevronRight size={18}/></button></div>
      <div className="list-heading"><h2>我的清单 <span>{todayTasks.length}</span></h2><div className="inline-actions">{day!==today&&<button className="text-button" onClick={()=>setDay(today)}>回到今天</button>}<button className="icon-button" onClick={()=>setModal({type:'calendar'})} aria-label="选择日期"><CalendarDays size={20}/></button><button className="icon-button" onClick={()=>setModal({type:'search'})} aria-label="搜索所有计划"><Search size={20}/></button></div></div>
      <div className="filters">{[['all','全部'],['active','待完成'],['doing','进行中'],['done','已完成']].map(([k,v])=><button className={filter===k?'active':''} key={k} onClick={()=>setFilter(k)}>{v}</button>)}</div>
      {sample&&<div className="sample-banner"><Sparkles size={15}/>示例任务 · 随便体验，不会发送提醒<button onClick={()=>mutate('samples','DELETE',{}, {success:'示例已收起，可以开始自己的计划了'})}>收起</button></div>}
      {day===today&&overdue.length>0&&filter!=='done'&&<details className="overdue-box"><summary><Clock size={16}/>{overdue.length} 件之前的小事，等你重新安排<ChevronDown size={16}/></summary><div className="task-stack">{overdue.filter(matches).map(t=><TaskCard key={t.id} task={t} now={now} onOpen={()=>setModal({type:'detail',id:t.id})} onToggle={()=>toggle(t)} busy={busy}/>)}</div></details>}
      <motion.div className="task-stack" layout><AnimatePresence initial={false}>{list.map(t=><TaskCard key={t.id} task={t} now={now} onOpen={()=>setModal({type:'detail',id:t.id})} onToggle={()=>toggle(t)} busy={busy}/>)}</AnimatePresence></motion.div>
      {!list.length&&<Empty title={todayTasks.length?'这里暂时空空的':'给这一天，留一点期待'} text={todayTasks.length?'切换筛选，看看其他小事。':'不用安排得满满当当。一件想做的小事，就是很好的开始。'} action={todayTasks.length?null:()=>openAdd()} samples={!tasks.length?()=>mutate('samples','POST',{}):null}/>}
      {!!list.length&&<button className="quick-add" onClick={()=>openAdd()}><Plus size={20}/><span>再添一件想做的小事</span><kbd>＋</kbd></button>}
      <div className="gentle-note"><Leaf size={15}/>{percent===100&&todayTasks.length?'做完了就好好休息，今天已经很棒。':'慢慢来，你正在成为想成为的自己。'}</div>
    </>}
    {page==='plans'&&<><div className="page-heading"><div><p className="eyebrow">给未来的自己</p><h1>把期待，走成现实<span className="heading-spark purple-text">✦</span></h1><p className="muted">大大的目标，拆成小小的下一步。</p></div><button className="button primary desktop-add" onClick={()=>openAdd('goal')}><Plus size={19}/>新建计划</button></div>
      <div className="plan-intro"><div className="plan-intro-icon"><Map size={28}/></div><div><h3>每段旅程，都有自己的节奏</h3><p>设一个目标，标出里程碑，剩下的交给每一天。</p></div><Sparkles size={24}/></div>
      <div className="filters">{[['all','全部计划'],['active','进行中'],['done','已完成'],['paused','已暂停']].map(([k,v])=><button key={k} onClick={()=>setFilter(k)} className={filter===k?'active':''}>{v}</button>)}</div>
      <div className="goal-grid">{goals.filter(matches).map(t=><GoalCard key={t.id} task={t} now={now} onOpen={()=>setModal({type:'detail',id:t.id})}/>)}</div>
      {!goals.filter(matches).length&&<Empty title="下一段旅程，想去哪里？" text="读一本书、学一项技能，或完成一件惦记很久的事。" action={()=>openAdd('goal')} label="写下我的长期计划"/>}
      {goals.length>0&&<button className="new-goal-card" onClick={()=>openAdd('goal')}><Plus size={24}/>开启一段新旅程</button>}
    </>}
    {page==='growth'&&<><div className="page-heading"><div><p className="eyebrow">每一步都没有白走</p><h1>看看你，走了多远<span className="heading-spark orange-text">✦</span></h1><p className="muted">不和别人比赛，只记录自己的前进。</p></div></div><section className="growth-hero"><div><span className="pill light"><Star size={15}/>Lv.{Math.floor(stats.xp/100)+1} · {stats.xp<100?'初芽探索者':stats.xp<500?'向阳行动派':'坚定生长家'}</span><h2>{stats.completed?'这 '+stats.completed+' 次行动，都是你的光。':'第一份成就，就在下一步。'}</h2><p>每完成一件小事 +10 成长值，长期计划 +50。</p><Progress value={stats.xp%100} color="orange"/><small>{stats.xp%100} / 100 · 距离下一级还有 {100-stats.xp%100}</small></div><Sprout/></section>
      <div className="stat-grid"><div><Flame/><b>{stats.streak}<small>天</small></b><span>连续行动</span></div><div><CheckCheck/><b>{stats.completed}<small>件</small></b><span>已完成的小事</span></div><div><Star/><b>{stats.xp}<small>点</small></b><span>积累的成长值</span></div></div>
      <section className="white-panel"><div className="section-title"><h2>这一周的小脚印</h2><span>近 7 天</span></div><div className="week-chart">{stats.week.map(w=><div key={w.day}><b>{w.count||''}</b><div className="bar-track"><motion.div initial={{height:0}} animate={{height:Math.max(7,w.count/Math.max(3,...stats.week.map(x=>x.count))*100)+'%'}}/></div><span>{w.day===today?'今天':weekday(w.day).replace('星期','周')}</span></div>)}</div></section>
      <div className="section-title"><h2>完成的瞬间</h2><span>{tasks.filter(t=>t.status==='done'&&!t.sample).length} 件</span></div><div className="task-stack">{tasks.filter(t=>t.status==='done'&&!t.sample).sort((a,b)=>b.completedAt-a.completedAt).slice(0,30).map(t=><TaskCard key={t.id} task={t} onOpen={()=>setModal({type:'detail',id:t.id})} onToggle={()=>toggle(t)} busy={busy}/>)}</div>{!stats.completed&&<div className="small-empty"><Star size={30}/><p>你的第一个完成瞬间，会被好好记住。</p></div>}
    </>}
    {page==='settings'&&<><div className="page-heading"><div><p className="eyebrow">按你的节奏来</p><h1>我的小步<span className="heading-spark">✦</span></h1><p className="muted">计划属于你，提醒也由你决定。</p></div></div>
      <section className="profile-card"><Sprout/><div><h2>{settings.name==='你'?'今天也很期待你':settings.name+'，慢慢来'}</h2><p>Lv.{Math.floor(stats.xp/100)+1} · 每天一点，走得更远</p></div><button className="icon-button" onClick={()=>setModal({type:'name'})} aria-label="修改昵称"><MoreHorizontal/></button></section>
      <section className="white-panel"><div className="section-title"><h2><Bell size={20}/>温柔提醒</h2><span className={'connection-pill '+(state.push.subscribed?'connected':'')}>{state.push.subscribed?'设备已连接':'尚未连接'}</span></div><p className="setting-intro">重要的事会来找你。完成后就不再催促。</p><div className="button-row"><button className="button primary" onClick={enablePush}><Bell size={17}/>{state.push.subscribed?'连接当前设备':'开启手机通知'}</button><button className="button secondary" disabled={busy||!state.push.subscribed} onClick={()=>mutate('push/test','POST',{}, {success:'10 秒后送达，请回到手机桌面查看'})}><Send size={17}/>测试通知</button></div>
      <SettingToggle label="任务提醒" description="到期前、到期时和未完成时，轻轻提醒" value={settings.notifications} disabled={busy} onChange={v=>mutate('settings','PATCH',{notifications:v})}/>
      <SettingToggle label="早间计划" description={'每天 '+settings.morningTime+'，看看今天想做什么'} value={settings.morning} disabled={busy} onChange={v=>mutate('settings','PATCH',{morning:v})}/>
      <SettingToggle label="晚间回顾" description={'每天 '+settings.eveningTime+'，给未完成的小事留点时间'} value={settings.evening} disabled={busy} onChange={v=>mutate('settings','PATCH',{evening:v})}/>
      <button className="setting-link" onClick={()=>setModal({type:'reminderSettings'})}><span><Moon size={20}/><span>提醒时间与免打扰<small>{settings.quietStart}–{settings.quietEnd} 安静休息 · 每天最多 {settings.dailyLimit} 条</small></span></span><ChevronRight size={18}/></button>
      <button className="setting-link" onClick={()=>mutate('settings','PATCH',{snoozedUntil:settings.snoozedUntil>now?0:Date.now()+86400000},{success:settings.snoozedUntil>now?'提醒已恢复':'今天先不打扰你，24 小时后恢复'})}><span><BellOff size={20}/>{settings.snoozedUntil>now?'恢复提醒':'让提醒休息 24 小时'}</span><ChevronRight size={18}/></button></section>
      <section className="white-panel"><div className="section-title"><h2>用起来，也要喜欢</h2></div><SettingToggle label="完成小庆祝" description="每次完成，都有一点开心的反馈" value={settings.celebrate} disabled={busy} onChange={v=>mutate('settings','PATCH',{celebrate:v})}/><div className="setting-row"><span>外观</span><div className="segmented compact">{[['light','浅色'],['dark','深色'],['system','跟随系统']].map(([k,v])=><button key={k} className={settings.theme===k?'selected':''} onClick={()=>mutate('settings','PATCH',{theme:k})}>{v}</button>)}</div></div><button className="setting-link" onClick={()=>setModal({type:'install'})}><span><Plus size={20}/>添加到手机桌面</span><ChevronRight size={18}/></button></section>
      <section className="white-panel"><div className="section-title"><h2>我的数据</h2><span><Cloud size={16}/> 服务器保存</span></div><button className="setting-link" onClick={()=>setModal({type:'trash'})}><span><Archive size={20}/>回收站<small>{state.trash.length} 件</small></span><ChevronRight size={18}/></button><a className="setting-link" href={BASE+'api/export'} download><span><Download size={20}/>导出所有计划</span><ChevronRight size={18}/></a><button className="setting-link" onClick={()=>mutate('samples','POST',{}, {success:'示例已添加，可在今天和长期计划里体验'})}><span><Sparkles size={20}/>体验示例计划</span><ChevronRight size={18}/></button>{sample&&<button className="setting-link" onClick={()=>mutate('samples','DELETE',{}, {success:'示例已收起'})}><span><Trash2 size={20}/>收起示例计划</span><ChevronRight size={18}/></button>}</section><p className="settings-footer">小步 1.0 · 为自己的每一天而做<br/>所有计划存放在你的服务器 · 北京时间</p>
    </>}
    </motion.div></AnimatePresence></main>
    <aside className="right-rail"><div className="rail-title"><span>一点点，变更好</span><Sparkles size={19}/></div><section className="rail-card journey-card"><div className="section-title"><h3>正在走的旅程</h3><Map size={20}/></div>{goal?<><span className={'category-pill '+goal.color}>{goal.category}</span><h4>{goal.title}</h4><Progress value={goal.progress} color={goal.color}/><div className="rail-progress"><span>{goal.steps.filter(s=>s.done).length} / {goal.steps.length||1} 个节点</span><b>{goal.progress}%</b></div><div className="mini-path">{Array.from({length:Math.min(goal.steps.length||4,5)},(_,i)=><span key={i} className={goal.steps[i]?.done?'complete':i===goal.steps.findIndex(s=>!s.done)?'current':''}>{goal.steps[i]?.done?<Check size={14}/>:i+1}</span>)}</div><button className="text-button" onClick={()=>setModal({type:'detail',id:goal.id})}>走好下一步 <ArrowRight size={16}/></button></>:<><div className="empty-journey"><Map size={38}/></div><h4>给未来种一颗种子</h4><p>把一直想做的事，拆成几个小小的里程碑。</p><button className="text-button" onClick={()=>openAdd('goal')}>开启我的旅程 <ArrowRight size={16}/></button></>}</section><section className="rail-card weekly-card"><div className="section-title"><h3>这周的你</h3><Leaf size={19}/></div><div className="week-dots">{stats.week.map(w=><div key={w.day}><span className={w.count?'done':''}>{w.count?<Check size={16}/>:<i/>}</span><small>{weekday(w.day).slice(-1)}</small></div>)}</div><p>小小的坚持，也值得被看见。</p></section><div className="quote-card"><span>“</span><p>你不必看清整段阶梯，<br/>只需要迈出下一步。</p><small>给正在努力的你</small></div><button className="rail-help" onClick={()=>setModal({type:'install'})}><span className="phone-glyph">▯</span><div><b>把小步装进口袋</b><small>添加到桌面，随时记录灵感</small></div><ChevronRight size={18}/></button></aside></div>
    </div><nav className="bottom-nav" aria-label="底部导航">{nav.map(n=><button key={n.id} onClick={()=>changePage(n.id)} className={page===n.id?'active':''} aria-current={page===n.id?'page':undefined}><n.icon size={23}/><span>{n.id==='plans'?'计划':n.id==='growth'?'足迹':n.label}</span></button>)}</nav>{['today','plans'].includes(page)&&<button className="fab" aria-label={page==='plans'?'新建长期计划':'添加任务'} onClick={()=>openAdd(page==='plans'?'goal':'task')}><Plus size={28} strokeWidth={3}/></button>}
    </div>
    <AnimatePresence>{modal&&<Modal title={modal.type==='form'?(modal.task?'编辑计划':modal.kind==='goal'?'开启一段新旅程':'记下一件小事'):modal.type==='detail'?'每一步，都算数':modal.type==='calendar'?'选一个日子':modal.type==='search'?'找到你的小计划':modal.type==='install'?'把小步装进口袋':modal.type==='notifications'?'消息小站':modal.type==='reminderSettings'?'按你的时间提醒':modal.type==='trash'?'暂时收起的计划':modal.type==='delete'?'给计划留个退路':'怎么称呼你'} onClose={()=>!busy&&setModal(null)} wide={modal.type==='detail'}>
      {modal.type==='form'&&<TaskForm initial={modal.task} kind={modal.kind} day={day} today={today} settings={settings} busy={busy} onSave={async(task,id)=>{const result=modal.task?await patchTask(modal.task,task,{close:true,success:'计划已更新'}):await mutate('tasks','POST',{task,id},{close:true,success:task.kind==='goal'?'新旅程开始了，一步步来！':'记下啦，期待你的小小行动'});if(result&&task.kind==='goal')changePage('plans');else if(result){setDay(task.day);changePage('today');}return result;}}/>}
      {modal.type==='detail'&&(selected?<TaskDetail task={selected} now={now} zone={settings.timezone} busy={busy} onChange={patch=>patchTask(selected,patch)} onComplete={()=>toggle(selected)} onEdit={()=>setModal({type:'form',task:selected,kind:selected.kind})} onDelete={()=>setModal({type:'delete',id:selected.id})} onPostpone={()=>patchTask(selected,{day:dateAdd(today,1),dueAt:selected.dueAt?zonedISO(dateAdd(today,1),localParts(selected.dueAt,settings.timezone).time,settings.timezone):null},{success:'已放到明天，按自己的节奏来'})} onStopRepeat={()=>mutate('series/'+selected.seriesId+'/stop','POST',{}, {success:'重复已停止，已完成的记录会保留'})}/>:<div className="small-empty">这件计划已收起或删除。</div>)}
      {modal.type==='delete'&&selected&&<div className="sheet-body"><div className="delete-art"><Archive size={40}/></div><h3>先把「{selected.title}」收起来？</h3><p className="muted">会移到回收站，随时可以找回来。{selected.seriesId?'这也会停止后续重复任务。':''}</p><div className="button-row"><button className="button secondary" onClick={()=>setModal({type:'detail',id:selected.id})}>再想想</button><button className="button danger" disabled={busy} onClick={()=>remove(selected)}>移到回收站</button></div></div>}
      {modal.type==='calendar'&&<Calendar value={day} tasks={tasks} onSelect={d=>{setDay(d);setModal(null);}} today={today}/>}
      {modal.type==='search'&&<SearchTasks tasks={tasks} onOpen={id=>setModal({type:'detail',id})}/>}
      {modal.type==='install'&&<div className="sheet-body install-body"><Sprout/><h3>从桌面打开，就像一个 App</h3><p>在 iPhone 的 Safari 中打开你的私人入口，然后：</p><ol><li><b>1</b><span>点地址栏的「⋯」，选择<strong>共享</strong></span></li><li><b>2</b><span>选择<strong>添加到主屏幕</strong>，保持「作为网页 App 打开」</span></li><li><b>3</b><span>从桌面打开<strong>小步</strong>，在「我的」中开启手机通知</span></li></ol><div className="tip"><ShieldCheck size={18}/>这是你的私人空间，请妥善保存入口地址。</div><button className="button primary full" onClick={()=>setModal(null)}>知道啦</button></div>}
      {modal.type==='notifications'&&<div className="sheet-body">{state.notifications.length?state.notifications.map(n=><div className="notification-row" key={n.id}><span className="notification-icon"><Bell size={20}/></span><div><b>{n.payload.type==='test'?'通知连接测试':n.payload.type==='morning'?'早间计划':n.payload.type==='evening'?'晚间回顾':tasks.find(t=>t.id===n.payload.taskId)?.title||'任务提醒'}</b><p>{({pending:'等待发送',sending:'正在发送',accepted:'推送服务已接收',shown:'设备已显示',failed:'发送未成功',expired:'已过期',cancelled:'已取消'})[n.status]}</p><small>{new Date(n.created_at).toLocaleString('zh-CN',{timeZone:settings.timezone})}{n.last_error?' · '+n.last_error:''}</small></div></div>):<div className="small-empty"><Bell size={40}/><h3>消息小站，准备好了</h3><p>发送过的提醒会记录在这里。</p></div>}<button className="button secondary full" onClick={()=>{setModal(null);changePage('settings');}}>管理提醒</button></div>}
      {modal.type==='reminderSettings'&&<ReminderForm settings={settings} busy={busy} save={p=>mutate('settings','PATCH',p,{close:true,success:'提醒节奏已更新'})}/>}
      {modal.type==='name'&&<NameForm value={settings.name} busy={busy} save={name=>mutate('settings','PATCH',{name},{close:true})}/>}
      {modal.type==='trash'&&<div className="sheet-body">{state.trash.length?state.trash.map(t=><div className="trash-row" key={t.id}><span><b>{t.title}</b><small>{t.kind==='goal'?'长期计划':'每日任务'} · {t.sample?'示例':'可恢复'}</small></span><button className="button secondary small" disabled={busy} onClick={()=>mutate('tasks/'+t.id+'/restore','POST',{}, {success:'计划已找回'})}><RotateCcw size={16}/>恢复</button></div>):<div className="small-empty"><Archive size={36}/><p>这里还没有收起的计划。</p></div>}</div>}
    </Modal>}</AnimatePresence>
    <AnimatePresence>{toast&&<motion.div className="toast" role="status" initial={{y:30,opacity:0}} animate={{y:0,opacity:1}} exit={{y:20,opacity:0}}><span>{toast.message}</span>{toast.action&&<button onClick={()=>{toast.action.run();setToast(null);}}>{toast.action.label}</button>}<button className="toast-close" onClick={()=>setToast(null)} aria-label="关闭提示"><X size={15}/></button></motion.div>}</AnimatePresence>
    {party>0&&<div className="confetti" aria-hidden="true">{Array.from({length:32},(_,i)=><i key={party+'-'+i} style={{'--x':(Math.sin(i*13)*44)+'vw','--y':(-35-Math.abs(Math.cos(i*7))*40)+'vh','--r':(i*71)+'deg','--delay':(i%4)*.03+'s',background:['#8fd13b','#ffc758','#a998ee','#7cd3dc','#f4a1ab'][i%5]}}/>)}</div>}
  </MotionConfig>;
}
function TaskCard({task:t,onOpen,onToggle,busy,now=Date.now()}){
  const Icon=icons[t.category]||Leaf;
  return <motion.article layout initial={{opacity:0,y:12}} animate={{opacity:1,y:0}} exit={{opacity:0,height:0,marginBottom:0}} transition={{duration:.22}} className={'task-card '+(t.status==='done'?'completed ':'')+(t.status==='doing'?'in-progress ':'')+t.color}>
    <button className={'check-button '+(t.status==='done'?'checked':'')} disabled={busy} onClick={onToggle} aria-label={(t.status==='done'?'重新打开':'完成')+' '+t.title} aria-pressed={t.status==='done'}>{t.status==='done'?<Check size={19} strokeWidth={3}/>:t.status==='doing'?<span/>:null}</button>
    <button className="task-content" onClick={onOpen}><div className="task-title"><h3>{t.title}</h3>{t.priority==='high'&&t.status!=='done'&&<Flag size={14} className="priority-flag" fill="currentColor"/>}</div><div className="task-meta"><span className={'category-label '+t.color}><Icon size={13}/>{t.category}</span>{t.repeat!=='none'&&<span><Repeat2 size={12}/>{t.repeat==='daily'?'每天':'工作日'}</span>}{t.steps.length>0&&<span><CheckCheck size={13}/>{t.steps.filter(s=>s.done).length}/{t.steps.length}</span>}{t.status==='paused'&&<span><Pause size={12}/>暂停中</span>}{t.sample&&<span>示例</span>}{t.dueAt&&t.status!=='done'&&<span className={Date.parse(t.dueAt)<now?'late':''}><Clock size={12}/>{dueText(t.dueAt,now)}</span>}</div>{t.status==='doing'&&<div className="task-progress"><Progress value={t.progress} color={t.color}/><span>{t.progress}%</span></div>}</button><button className="task-open" onClick={onOpen} aria-label={'查看 '+t.title}><ChevronRight size={19}/></button>
  </motion.article>;
}
function GoalCard({task:t,onOpen,now}){
  const Icon=icons[t.category];return <motion.button layout className={'goal-card '+t.color} onClick={onOpen} whileHover={{y:-3}} whileTap={{scale:.985}}><div className="goal-card-top"><span className="goal-icon"><Icon size={27}/></span><span className="goal-status">{statusLabel[t.status]}</span></div><h3>{t.title}</h3><p>{t.note||'每完成一个节点，就更靠近想要的自己。'}</p><div className="goal-card-progress"><b>{t.progress}<small>%</small></b><span>{t.steps.filter(s=>s.done).length}/{t.steps.length||1} 个节点</span></div><Progress value={t.progress} color={t.color}/><footer><span>{t.dueAt?<><Clock size={14}/>{dueText(t.dueAt,now)}</>:<><Leaf size={14}/>按自己的节奏前进</>}</span><span className="goal-arrow"><ArrowUpRight size={19}/></span></footer></motion.button>;
}
function SettingToggle({label,description,value,onChange,disabled}){return <div className="setting-row"><div><b>{label}</b><small>{description}</small></div><button type="button" role="switch" aria-label={label} aria-checked={value} disabled={disabled} className={'switch '+(value?'on':'')} onClick={()=>onChange(!value)}><span/></button></div>;}
function TaskForm({initial,kind,day,today,settings,busy,onSave}){
  const id=useRef(uid()),parts=localParts(initial?.dueAt,settings.timezone);
  const [form,setForm]=useState(initial||{kind,title:'',note:'',day:day||today,dueAt:null,category:kind==='goal'?'学习':'生活',priority:'normal',status:'todo',progress:0,steps:[],repeat:'none',reminder:'gentle',color:kind==='goal'?'purple':'green'});
  const [more,setMore]=useState(!!initial),[hasDue,setHasDue]=useState(!!initial?.dueAt),[dueDay,setDueDay]=useState(parts.day||day||today),[dueTime,setDueTime]=useState(parts.time||'20:00'),[error,setError]=useState('');
  const set=(k,v)=>setForm(f=>({...f,[k]:v}));const isGoal=form.kind==='goal';
  async function submit(e){e.preventDefault();setError('');if(!form.title.trim()){setError('给这件小事起个名字吧');return;}if(form.steps.some(s=>!s.title.trim())){setError('还有一个节点没写名字');return;}
    const fields=['title','note','kind','day','category','priority','status','progress','steps','reminder','repeat','color'];const payload=Object.fromEntries(fields.map(k=>[k,form[k]]));payload.dueAt=hasDue?zonedISO(dueDay,dueTime,settings.timezone):null;
    if(!initial){delete payload.status;delete payload.progress;}await onSave(payload,id.current);
  }
  return <form onSubmit={submit} className="task-form"><div className="sheet-body">
    {!initial&&<div className="segmented kind-picker"><button type="button" className={!isGoal?'selected':''} onClick={()=>{set('kind','task');set('color','green');}}><Sun size={18}/>每日任务</button><button type="button" className={isGoal?'selected':''} onClick={()=>{set('kind','goal');set('repeat','none');set('color','purple');}}><Map size={18}/>长期计划</button></div>}
    <label className="sr-only" htmlFor="task-title">任务名称</label><textarea id="task-title" className="title-input" rows={2} placeholder={isGoal?'一直想做的那件事是…':'今天，想做点什么？'} maxLength={160} required value={form.title} onChange={e=>set('title',e.target.value)} autoFocus/>
    <div className="date-presets">{[['今天',today],['明天',dateAdd(today,1)],['下周',dateAdd(today,7)]].map(([label,d])=><button key={label} type="button" className={form.day===d?'selected':''} onClick={()=>{set('day',d);if(!hasDue)setDueDay(d);}}>{label}</button>)}<label className="date-preset"><CalendarDays size={15}/><input aria-label={isGoal?'开始日期':'计划日期'} type="date" required value={form.day} onInput={e=>{set('day',e.target.value);if(!hasDue)setDueDay(e.target.value);}}/></label></div>
    <div className="field-label"><span>放进哪个小口袋</span></div><div className="category-picker">{Object.entries(icons).map(([label,Icon])=><button key={label} type="button" className={form.category===label?'selected':''} onClick={()=>set('category',label)}><Icon size={17}/>{label}</button>)}</div>
    {(isGoal||more)&&<><div className="field-label"><span>{isGoal?'拆成几个小小的里程碑':'把这件事拆成小步骤'}</span><small>{form.steps.length}/40</small></div><div className="steps-editor">{form.steps.map((s,i)=><div className="step-edit" key={s.id}><span className="step-number">{i+1}</span><div><input aria-label={'节点 '+(i+1)+' 名称'} placeholder="写下一个能做到的小步骤" maxLength={120} value={s.title} onChange={e=>set('steps',form.steps.map(x=>x.id===s.id?{...x,title:e.target.value}:x))}/>{isGoal&&<label className="step-date"><CalendarDays size={13}/><input aria-label={'节点 '+(i+1)+' 截止日期'} type="date" value={localParts(s.dueAt,settings.timezone).day} onInput={e=>set('steps',form.steps.map(x=>x.id===s.id?{...x,dueAt:e.target.value?zonedISO(e.target.value,'20:00',settings.timezone):null}:x))}/></label>}</div><button type="button" className="icon-button" aria-label={'移除节点 '+(i+1)} onClick={()=>set('steps',form.steps.filter(x=>x.id!==s.id))}><X size={16}/></button></div>)}</div><button type="button" className="add-step" disabled={form.steps.length>=40} onClick={()=>set('steps',[...form.steps,{id:uid(),title:'',progress:0,done:false,dueAt:null}])}><Plus size={17}/>添加{isGoal?'里程碑':'步骤'}</button></>}
    <button type="button" className="more-form" onClick={()=>setMore(!more)}><Settings2 size={17}/>{more?'收起更多设置':'截止时间、提醒和更多设置'}<ChevronDown className={more?'rotated':''} size={17}/></button>
    <AnimatePresence>{more&&<motion.div initial={{height:0,opacity:0}} animate={{height:'auto',opacity:1}} exit={{height:0,opacity:0}} className="advanced-form"><div className="field-label"><label htmlFor="task-note">给自己留句话</label></div><textarea id="task-note" className="note-input" placeholder="为什么想做？有什么需要记住的？" maxLength={4000} rows={3} value={form.note} onChange={e=>set('note',e.target.value)}/>
      <SettingToggle label="设置截止时间" description="可以收到剩余时间和到期提醒" value={hasDue} onChange={setHasDue}/>{hasDue&&<div className="two-fields"><label>截止日期<input type="date" required value={dueDay} onInput={e=>setDueDay(e.target.value)}/></label><label>时间 · 北京时间<input type="time" required value={dueTime} onInput={e=>setDueTime(e.target.value)}/></label></div>}
      <div className="two-fields"><label>提醒我<select value={form.reminder} onChange={e=>set('reminder',e.target.value)}><option value="gentle">温柔提醒</option><option value="persistent">多督促一点</option><option value="off">这件事不提醒</option></select></label><label>重要程度<select value={form.priority} onChange={e=>set('priority',e.target.value)}><option value="normal">平常心完成</option><option value="high">今天的重点</option></select></label></div>
      {!isGoal&&<label className="select-field">重复节奏<select value={form.repeat} onChange={e=>set('repeat',e.target.value)}><option value="none">只做这一次</option><option value="daily">每天一小步</option><option value="weekdays">每个工作日</option></select></label>}
      <div className="field-label"><span>选一个喜欢的颜色</span></div><div className="color-picker">{[['green','芽绿'],['purple','浅紫'],['blue','晴蓝'],['orange','暖橙']].map(([c,label])=><button type="button" key={c} aria-label={label} aria-pressed={form.color===c} className={c+' '+(form.color===c?'selected':'')} onClick={()=>set('color',c)}>{form.color===c&&<Check size={18}/>}</button>)}</div>
      <p className="form-note">{form.reminder==='gentle'?'温柔提醒：提前 30 分钟、到期时，逾期后每天最多提醒一次。':form.reminder==='persistent'?'多督促一点：提前 1 小时、10 分钟、到期时，逾期后每 3 小时提醒。':'这件计划不会触发提醒。'} 所有提醒遵循免打扰和每日总上限。</p>{initial?.seriesId&&<p className="form-note">本次编辑仅修改当前任务；更改重复节奏会重新安排之后的任务。</p>}
    </motion.div>}</AnimatePresence>{error&&<p className="form-error" role="alert">{error}</p>}
    </div><footer className="sheet-footer"><span><Leaf size={15}/>{isGoal?'大目标，从小步开始':'记下来，就是好的开始'}</span><button type="submit" className="button primary" disabled={busy}>{busy?<LoaderCircle className="spin" size={19}/>:<Plus size={19}/>} {initial?'保存修改':isGoal?'开启旅程':'加入计划'}</button></footer></form>;
}
function TaskDetail({task:t,now,zone,busy,onChange,onComplete,onEdit,onDelete,onPostpone,onStopRepeat}){
  const [draft,setDraft]=useState(t.progress);useEffect(()=>setDraft(t.progress),[t.progress]);const Icon=icons[t.category];
  return <div className="sheet-body detail-body"><div className="detail-tags"><span className={'category-pill '+t.color}><Icon size={14}/>{t.category}</span><span className="pill">{t.kind==='goal'?'长期计划':'每日任务'}</span>{t.sample&&<span className="pill">示例</span>}<button className="text-button" onClick={onEdit}>编辑 <Settings2 size={15}/></button></div><h2 className="detail-title">{t.title}</h2>{t.note&&<p className="detail-note">{t.note}</p>}<div className="detail-dates"><span><CalendarDays size={16}/>{dayLabel(t.day)}{t.kind==='goal'?'开始':''}</span>{t.dueAt&&<span className={Date.parse(t.dueAt)<now&&t.status!=='done'?'late':''}><Clock size={16}/>{t.status==='done'?'已完成':dueText(t.dueAt,now)}</span>}</div>
    <div className="status-picker">{[['todo','未开始'],['doing','进行中'],['paused','暂停']].map(([k,label])=><button key={k} disabled={busy} className={t.status===k?'selected':''} onClick={()=>onChange({status:k,...(k==='doing'&&t.progress===100?{progress:0,steps:t.steps.map(s=>({...s,progress:0,done:false}))}:{})})}>{k==='doing'?<Play size={14}/>:k==='paused'?<Pause size={14}/>:<Sun size={14}/>} {label}</button>)}</div>
    <section className={'detail-progress '+t.color}><div><span>已经走过</span><b>{t.progress}<small>%</small></b></div><Progress value={t.progress} color={t.color}/>{!t.steps.length&&<><label className="range-label" htmlFor="manual-progress">更新当前进度 <b>{draft}%</b></label><input id="manual-progress" className="progress-slider" type="range" min="0" max="100" step="5" value={draft} disabled={busy} onChange={e=>setDraft(Number(e.target.value))}/>{draft!==t.progress&&<button className="button secondary small" disabled={busy} onClick={()=>onChange({progress:draft,status:draft===100?'done':draft>0?'doing':'todo'})}>保存 {draft}% 进度</button>}</>}</section>
    {t.steps.length>0&&<div className="journey"><div className="section-title"><h3>{t.kind==='goal'?'我的成长路线':'一步一步来'}</h3><span>{t.steps.filter(s=>s.done).length}/{t.steps.length}</span></div>{t.steps.map((s,i)=><div className={'journey-step '+(s.done?'done':i===t.steps.findIndex(n=>!n.done)?'current':'')} key={s.id}><button className="step-orb" disabled={busy} aria-label={(s.done?'取消完成节点 ':'完成节点 ')+s.title} onClick={()=>onChange({steps:t.steps.map(x=>x.id===s.id?{...x,progress:s.done?0:100,done:!s.done}:x)})}>{s.done?<Check size={22} strokeWidth={3}/>:i+1}</button><div className="step-info"><h4>{s.title}</h4><p>{s.done?'已经完成，真不错':s.dueAt?dayLabel(localParts(s.dueAt,zone).day)+' · '+dueText(s.dueAt,now):s.progress?'已前进 '+s.progress+'%':'按自己的节奏来'}</p>{!s.done&&<div className="step-progress-actions"><Progress value={s.progress} color={t.color}/><button className="text-button" disabled={busy} onClick={()=>onChange({steps:t.steps.map(x=>x.id===s.id?{...x,progress:Math.min(100,x.progress+25)}:x)})}>+25%</button></div>}</div></div>)}</div>}
    <div className="detail-actions"><button className={'button '+(t.status==='done'?'secondary':'primary')+' full'} disabled={busy} onClick={onComplete}>{t.status==='done'?<RotateCcw size={20}/>:<Check size={20}/>} {t.status==='done'?'重新打开这件事':'我完成啦！'}</button><div className="button-row">{t.kind==='task'&&t.status!=='done'&&<button className="button secondary" disabled={busy} onClick={onPostpone}><CalendarDays size={17}/>放到明天</button>}<button className="button ghost" onClick={onDelete}><Archive size={17}/>收起来</button></div>{t.seriesId&&t.repeat!=='none'&&<button className="text-button" disabled={busy} onClick={onStopRepeat}><Repeat2 size={16}/>停止后续重复</button>}</div>
  </div>;
}
function Calendar({value,onSelect,tasks,today}){
  const [month,setMonth]=useState(value.slice(0,7));const first=month+'-01',offset=(new Date(first+'T12:00:00Z').getUTCDay()+6)%7,start=dateAdd(first,-offset);
  const move=n=>{const d=new Date(first+'T12:00:00Z');d.setUTCMonth(d.getUTCMonth()+n);setMonth(d.toISOString().slice(0,7));};
  return <div className="sheet-body"><div className="calendar-heading"><button className="icon-button" onClick={()=>move(-1)} aria-label="上个月"><ChevronLeft/></button><h3>{Number(month.slice(0,4))} 年 {Number(month.slice(5))} 月</h3><button className="icon-button" onClick={()=>move(1)} aria-label="下个月"><ChevronRight/></button></div><div className="calendar-grid">{['一','二','三','四','五','六','日'].map(d=><span className="calendar-weekday" key={d}>{d}</span>)}{Array.from({length:42},(_,i)=>{const d=dateAdd(start,i);return <button key={d} onClick={()=>onSelect(d)} aria-label={dayLabel(d)} className={(d===value?'selected ':'')+(d.slice(0,7)!==month?'faded ':'')+(d===today?'today':'')}><b>{Number(d.slice(-2))}</b><i className={tasks.some(t=>t.day===d&&t.kind==='task')?'has-task':''}/></button>;})}</div><button className="button secondary full" onClick={()=>onSelect(today)}>回到今天</button></div>;
}
function SearchTasks({tasks,onOpen}){const [q,setQ]=useState('');const list=tasks.filter(t=>q&&(t.title+t.note+t.steps.map(s=>s.title).join(' ')).toLowerCase().includes(q.toLowerCase())).slice(0,50);return <div className="sheet-body"><div className="search-input"><Search size={21}/><input autoFocus placeholder="搜索任务、备注或节点" aria-label="搜索计划" value={q} onChange={e=>setQ(e.target.value)}/></div><div className="search-results">{list.map(t=><button key={t.id} onClick={()=>onOpen(t.id)}><span><b>{t.title}</b><small>{t.kind==='goal'?'长期计划':dayLabel(t.day)} · {statusLabel[t.status]}</small></span><ChevronRight size={18}/></button>)}{!list.length&&<div className="small-empty">{q?'暂时没找到，换个关键词试试。':'想找的小事，输入几个字就好。'}</div>}</div></div>;}
function ReminderForm({settings,busy,save}){const [s,setS]=useState(settings);return <form onSubmit={e=>{e.preventDefault();save(Object.fromEntries(['quietStart','quietEnd','morningTime','eveningTime','dailyLimit'].map(k=>[k,s[k]])));}}><div className="sheet-body"><div className="tip"><Moon size={22}/>每天都给自己留一段安静的时间。以下时间均为北京时间。</div><div className="two-fields">{[['quietStart','免打扰开始'],['quietEnd','免打扰结束'],['morningTime','早间计划'],['eveningTime','晚间回顾']].map(([k,l])=><label key={k}>{l}<input type="time" required value={s[k]} onInput={e=>setS({...s,[k]:e.target.value})}/></label>)}</div><label className="select-field">每天最多提醒几次<select value={s.dailyLimit} onChange={e=>setS({...s,dailyLimit:Number(e.target.value)})}><option value={3}>3 次 · 少一点打扰</option><option value={6}>6 次 · 刚刚好的陪伴</option><option value={10}>10 次 · 多一点督促</option></select></label><p className="form-note">已完成、暂停和关闭提醒的任务不会催促。早晚回顾仅在有待办时发送。免打扰开始和结束相同表示全天允许提醒。</p></div><footer className="sheet-footer"><span>按你的节奏来</span><button className="button primary" disabled={busy}>保存设置</button></footer></form>;}
function NameForm({value,busy,save}){const [name,setName]=useState(value==='你'?'':value);return <form onSubmit={e=>{e.preventDefault();save(name.trim());}} className="sheet-body"><label className="select-field">你喜欢的称呼<input maxLength={30} required autoFocus value={name} placeholder="给自己一个喜欢的名字" onChange={e=>setName(e.target.value)}/></label><button className="button primary full" disabled={busy||!name.trim()}>就叫这个</button></form>;}
createRoot(document.getElementById('root')).render(<App/>);
